head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[multiselect > M > deleteItem]<br/>Multiselect 컴포넌트에서 특정 아이템을 제거합니다.",
    "validation" : [
        "index(필수) 파라미터로 제거하려는 아이템의 인덱스를 설정합니다.",
        "아이템의 인덱스는 0 부터 시작합니다.",
        "설정한 인덱스 위치의 아이템이 제거되고 이후 아이템의 인덱스가 하나씩 감소합니다.",
        "refresh(선택) 파라미터로 아이템이 BindItemSet 으로 정의된 경우 DataCollection 에 반영 여부를 설정합니다.",
        "refresh(선택) 파라미터로 true 설정 시 아이템이 정의된 DataCollection 에서 해당 아이템을 제거합니다.",
        "refresh(선택) 파라미터로 false 설정 시 아이템이 정의된 DataCollection 에서 해당 아이템을 제거하지 않습니다.",
        "refresh(선택) 파라미터를 생략하면 dataListAutoRefresh 속성값이 적용됩니다.",
        "리턴값으로 제거된 아이템을 객체로 반환합니다.",
        "index 파라미터값이 유효 범위를 벗어나면 null 이 반환되고 아이템은 제거되지 않습니다.",
        "리턴 객체의 label 속성값으로 제거된 아이템의 라벨값을 갖습니다.",
        "리턴 객체의 value 속성값으로 제거된 아이템의 Value 값을 갖습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 (BindItemSet: gdl_multiselect 바인딩)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // gdl_multiselect 재생성 (idempotent: 기존 dataList 제거 후 재생성)
    $c.gcm.createDataListMultiSelect();

    // comp 생성 함수 호출
    await $c.gcm.createBasicMultiSelect();
}



// deleteItem 호출
// par_index : 제거하려는 아이템의 인덱스
// par_refresh : 미설정/true/false (미설정 시 dataListAutoRefresh 속성값 적용)
scwin.btn_deleteItem_onclick = function (e) {
    let index = parseInt(par_index.getValue(), 10);
    let refresh = par_refresh.getText();
    let rtn = null;

    if (refresh === "") {
        rtn = target1.deleteItem(index);
    } else if (refresh === "true") {
        rtn = target1.deleteItem(index, true);
    } else {
        rtn = target1.deleteItem(index, false);
    }

    let refreshLabel = (refresh === "") ? "생략" : refresh;
    wf_body_bottom.getObj("scwin").setReturnValue("deleteItem(index=" + index + ", refresh=" + refreshLabel + ") 호출");
    wf_body_bottom.getObj("scwin").setReturnValue("result : " + rtn);
    if (rtn !== null && rtn !== undefined) {
        wf_body_bottom.getObj("scwin").setReturnValue("result.label : " + rtn.label);
        wf_body_bottom.getObj("scwin").setReturnValue("result.value : " + rtn.value);
    }
};



// MultiSelect 의 현재 아이템 목록 확인 (DOM, accessibility=true 시 button, false 시 td)
scwin.btn_getItems_onclick = function (e) {
    let count = target1.getItemCount();
    wf_body_bottom.getObj("scwin").setReturnValue("MultiSelect 아이템 수 : " + count);

    if (target1 && target1.render) {
        let labelDoms = target1.render.querySelectorAll("button.w2multiselect_acc_link, td.w2multiselect_td");
        labelDoms.forEach((el, idx) => {
            wf_body_bottom.getObj("scwin").setReturnValue("item index=" + idx + " 의 label : " + el.textContent);
        });
    }
};



// 바인딩된 DataList 의 현재 값 확인
scwin.btn_getDataList_onclick = function (e) {
    let rsData = gdl_multiselect.getAllJSON();

    wf_body_bottom.getObj("scwin").setReturnValue("DataList Row 수 : " + rsData.length);
    for (let i = 0; i < rsData.length; i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("Row[" + i + "] label=" + rsData[i].label + ", value=" + rsData[i].value);
    }
};
